// --- Schema Definition ---



export type GutBrainAxisProps = Record<string, any>;

// --- Main Component ---

const GutBrainAxis: React.FC<GutBrainAxisProps> = ({
  backgroundColor = "#fdfbf7",
  transparentBackground = false,
  durationInSeconds = 15,
  rotationSpeed = 0.5,
  orbitRx = 450,
  orbitRy = 220, // Tighter Ry so the orbit loops directly through Brain and Gut
  pulseIntensity = 0.4,
  centralTitle = "GUT-BRAIN",
  centralSubtitle = "AXIS",
  items = [
    { label: "NUTRIENT DELIVERY", iconIndex: 0 },
    { label: "STRESS", iconIndex: 1 },
    { label: "MOOD", iconIndex: 2 },
    { label: "ANXIETY", iconIndex: 3 },
    { label: "NEUROTRANSMITTERS", iconIndex: 4 },
    { label: "SECRETION", iconIndex: 5 },
    { label: "MOTILITY", iconIndex: 6 },
    { label: "MICROBIAL BALANCE", iconIndex: 7 },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Center coordinate reference points
  const cx = width / 2;
  const cy = height / 2;

  // Orbit rotation progress calculation
  const totalFrames = durationInSeconds * fps;
  const rawProgress = (frame / totalFrames) * rotationSpeed;
  
  // Custom interactive glow feedback loop:
  // We calculate real-time proximity of any orbiting node to the top (Brain) and bottom (Gut) positions.
  let brainGlowIntensity = 0;
  let gutGlowIntensity = 0;

  const resolvedItems = items.map((item, index) => {
    // Distribute nodes equally around the circle
    const baseAngle = (index / items.length) * 2 * Math.PI;
    // Apply clockwise continuous movement
    const angle = baseAngle + rawProgress * 2 * Math.PI;

    // Calculate proximity to the Brain (angle at 3 * Math.PI / 2)
    const sinVal = Math.sin(angle);
    if (sinVal < -0.8) {
      // Scale proximity from 0 (at sin=-0.8) to 1 (at sin=-1.0)
      const proximity = (sinVal - (-0.8)) / (-1.0 - (-0.8));
      brainGlowIntensity = Math.max(brainGlowIntensity, proximity);
    }

    // Calculate proximity to the Gut (angle at Math.PI / 2)
    if (sinVal > 0.8) {
      // Scale proximity from 0 (at sin=0.8) to 1 (at sin=1.0)
      const proximity = (sinVal - 0.8) / (1.0 - 0.8);
      gutGlowIntensity = Math.max(gutGlowIntensity, proximity);
    }

    return {
      ...item,
      angle,
    };
  });

  // Central Organs pulse logic
  const idlePulse = Math.sin(frame * 0.05) * 0.02;
  const brainScale = 1 + brainGlowIntensity * 0.12 * pulseIntensity + idlePulse;
  const brainShadowGlow = 10 + brainGlowIntensity * 25 * pulseIntensity;

  const gutScale = 1 + gutGlowIntensity * 0.12 * pulseIntensity + Math.sin(frame * 0.05 + Math.PI) * 0.02;
  const gutShadowGlow = 10 + gutGlowIntensity * 25 * pulseIntensity;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        overflow: "hidden",
        transition: "none",
      }}
    >
      {/* Decorative background overlay */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          background: "radial-gradient(circle, rgba(255,255,255,0) 40%, rgba(243,235,224,0.4) 100%)",
          pointerEvents: "none",
          zIndex: 0,
        }}
      />

      {/* Dynamic flowing orbit line */}
      <svg
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          pointerEvents: "none",
          zIndex: 1,
          transition: "none",
        }}
      >
        <defs>
          <linearGradient id="orbitGrad" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#f48695" stopOpacity={0.8} />
            <stop offset="50%" stopColor="#ffd3b6" stopOpacity={0.9} />
            <stop offset="100%" stopColor="#f48695" stopOpacity={0.8} />
          </linearGradient>
        </defs>
        <ellipse
          cx={cx}
          cy={cy}
          rx={orbitRx}
          ry={orbitRy}
          fill="none"
          stroke="url(#orbitGrad)"
          strokeWidth="4"
          strokeDasharray="10 15"
          strokeDashoffset={-frame * 1.5}
          style={{ transition: "none" }}
        />
      </svg>

      {/* --- Central Static Group --- */}
      
      {/* 1. Brain (Top-Center) */}
      <div
        style={{
          position: "absolute",
          left: cx,
          top: cy - height * 0.16,
          transform: `translate(-50%, -50%) scale(${brainScale})`,
          transformOrigin: "center center",
          zIndex: 5, // Anchored between background & foreground orbit z-indices
          filter: `drop-shadow(0px ${4 + brainGlowIntensity * 4}px ${brainShadowGlow}px rgba(244, 134, 149, ${0.15 + brainGlowIntensity * 0.5}))`,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          transition: "none",
        }}
      >
        <BrainSVG style={{ transition: "none" }} />
        {/* Playful star sparkles around brain */}
        <Sparkle
          style={{
            position: "absolute",
            left: -35,
            top: 40,
            transform: `scale(${1 + Math.sin(frame * 0.1) * 0.15}) rotate(${frame}deg)`,
            opacity: 0.8,
            transition: "none",
          }}
        />
        <Sparkle
          style={{
            position: "absolute",
            right: -25,
            top: 15,
            transform: `scale(${0.8 + Math.sin(frame * 0.1 + 1) * 0.15}) rotate(${-frame * 0.8}deg)`,
            opacity: 0.9,
            transition: "none",
          }}
        />
      </div>

      {/* 2. Central GUT-BRAIN AXIS Typography */}
      <div
        style={{
          position: "absolute",
          left: cx,
          top: cy,
          transform: "translate(-50%, -50%)",
          textAlign: "center",
          zIndex: 6,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          pointerEvents: "none",
          transition: "none",
        }}
      >
        <div
          style={{
            fontSize: "46px",
            fontWeight: 900,
            color: "#1e272e",
            letterSpacing: "5px",
            lineHeight: "1.1",
            textShadow: "0 2px 8px rgba(0,0,0,0.06)",
            transition: "none",
          }}
        >
          {centralTitle}
        </div>
        <div
          style={{
            fontSize: "30px",
            fontWeight: 700,
            color: "#34495e",
            letterSpacing: "10px",
            marginTop: "6px",
            opacity: 0.95,
            transition: "none",
          }}
        >
          {centralSubtitle}
        </div>
      </div>

      {/* 3. Stomach & Intestines (Bottom-Center) */}
      <div
        style={{
          position: "absolute",
          left: cx,
          top: cy + height * 0.19,
          transform: `translate(-50%, -50%) scale(${gutScale})`,
          transformOrigin: "center center",
          zIndex: 5,
          filter: `drop-shadow(0px ${4 + gutGlowIntensity * 4}px ${gutShadowGlow}px rgba(246, 65, 108, ${0.12 + gutGlowIntensity * 0.5}))`,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          transition: "none",
        }}
      >
        <GutSVG style={{ transition: "none" }} />
        {/* Playful star sparkles around gut */}
        <Sparkle
          style={{
            position: "absolute",
            left: -30,
            top: 20,
            transform: `scale(${0.9 + Math.sin(frame * 0.08) * 0.15}) rotate(${-frame * 0.5}deg)`,
            opacity: 0.8,
            transition: "none",
          }}
        />
        <Sparkle
          style={{
            position: "absolute",
            right: -30,
            top: 60,
            transform: `scale(${1.1 + Math.sin(frame * 0.08 + 2) * 0.15}) rotate(${frame * 0.6}deg)`,
            opacity: 0.95,
            transition: "none",
          }}
        />
      </div>


      {/* --- Orbiting Nodes Group --- */}
      {resolvedItems.map((item, index) => {
        const { angle, label, iconIndex } = item;

        // Calculate positions on elliptical trajectory
        const x = cx + orbitRx * Math.cos(angle);
        const y = cy + orbitRy * Math.sin(angle);

        // depthScale: simulate 3D projection (smaller at the back, larger in front)
        const depthScale = interpolate(Math.sin(angle), [-1, 1], [0.82, 1.15]);
        
        // depthOpacity: slightly fade nodes when at the back of the cycle
        const depthOpacity = interpolate(Math.sin(angle), [-1, 1], [0.75, 1.0]);

        // Dynamic 3D depth ordering:
        // Nodes behind the Brain/Gut (top half of orbit, Math.sin(angle) < 0) are rendered behind (zIndex = 4).
        // Nodes in front of the Brain/Gut (bottom half of orbit, Math.sin(angle) >= 0) are in front (zIndex = 10).
        const itemZIndex = Math.sin(angle) < 0 ? 4 : 10;

        return (
          <div
            key={index}
            style={{
              position: "absolute",
              left: x,
              top: y,
              transform: `translate(-50%, -50%) scale(${depthScale})`,
              opacity: depthOpacity,
              zIndex: itemZIndex,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              pointerEvents: "none",
              transition: "none",
            }}
          >
            {/* Circle Node Container */}
            <div
              style={{
                width: "110px",
                height: "110px",
                borderRadius: "50%",
                backgroundColor: "#fff6f2",
                border: "4px solid #f9c9b6",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                boxShadow: "0 10px 20px rgba(244, 134, 149, 0.15)",
                transition: "none",
              }}
            >
              {renderIcon(iconIndex)}
            </div>

            {/* Title text under the circle */}
            <div
              style={{
                position: "absolute",
                bottom: "-48px",
                width: "210px",
                textAlign: "center",
                fontSize: "13px",
                fontWeight: 800,
                color: "#1e272e",
                textTransform: "uppercase",
                letterSpacing: "1.2px",
                lineHeight: "1.2",
                textShadow: "0 1px 4px rgba(255, 255, 255, 0.8)",
                transition: "none",
              }}
            >
              {label}
            </div>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default GutBrainAxis;